class Solution:
    def idempotency(self, requests: list[list[str]]) -> list:
        records={}
        result=[]
        for key,payload in requests:
            if key not in records:records[key]=(payload,len(records)+1)
            stored,identifier=records[key]
            result.append(identifier if stored==payload else "conflict")
        return result

